from model import Summary

def run(data,limit):
 frames=[]
 cursor=0
 while cursor<len(data):
  start=cursor
  header=data[cursor]
  cursor+=1

  if header==255:
   continue

  if header==254:
   if len(data)-cursor<2:
    return Summary(frames,start,1)
   length=data[cursor] | (data[cursor+1]<<8)
   cursor+=2
  else:
   length=header

  if length>limit:
   return Summary(frames,start,3)
  if len(data)-cursor<length+1:
   return Summary(frames,start,1)

  value=data[cursor:cursor+length]
  if sum(value)%256!=data[cursor+length]:
   return Summary(frames,start,2)
  frames.append(value)
  cursor+=length+1

 return Summary(frames,len(data),0)

